use super::*;
use std::{io::Write,process::Stdio,sync::Mutex};
static WRITE:Mutex<()>=Mutex::new(());
#[derive(Serialize)]pub struct Snapshot{branches:Vec<String>,log:Vec<Commit>,staged:Vec<String>,unstaged:Vec<String>}
#[derive(Serialize)]pub struct Commit{hash:String,parents:Vec<String>,subject:String,author:String,date:String,refs:String}
#[derive(Serialize)]pub struct Diff{before:String,after:String}
fn relative(path:&str)->Result<(),String>{if path.is_empty()||Path::new(path).is_absolute()||Path::new(path).components().any(|c|!matches!(c,std::path::Component::Normal(_))){return Err("Invalid repository-relative path".into())}if path.split('/').any(|s|s==".git"){return Err("Git metadata protected".into())}Ok(())}
#[tauri::command]pub async fn git_snapshot(root:String,include_history:Option<bool>,branch:Option<String>,include_branches:Option<bool>)->Result<Snapshot,String>{tauri::async_runtime::spawn_blocking(move||{let p=root_path(&root)?;let need_history=include_history.unwrap_or(true);let need_branches=include_branches.unwrap_or(true)||branch.is_some();let branches:Vec<String>=if need_branches{text(git(&p,&["for-each-ref","--format=%(refname:short)","refs/heads","refs/remotes"])?).lines().map(str::to_string).collect()}else{Vec::new()};let mut log=Vec::new();if need_history&&git(&p,&["rev-parse","--verify","HEAD"]).is_ok(){let mut args=vec!["log","--topo-order","-200","--format=%H%x00%P%x00%s%x00%an%x00%ai%x00%D%x00"];let revision;if let Some(ref name)=branch{if !branches.contains(name){return Err("Unknown branch reference".into())}let full=if git(&p,&["show-ref","--verify",&format!("refs/heads/{}",name)]).is_ok(){format!("refs/heads/{}",name)}else{format!("refs/remotes/{}",name)};revision=text(git(&p,&["rev-parse","--verify",&full])?);args.push(&revision);}else{args.push("--all");}args.push("--");let bytes=git(&p,&args)?;let fields:Vec<_>=bytes.split(|b|*b==0).collect();for f in fields.chunks(6){if f.len()<6{break}let s=|i:usize|String::from_utf8_lossy(f[i]).trim().to_string();log.push(Commit{hash:s(0),parents:s(1).split_whitespace().map(str::to_string).collect(),subject:s(2),author:s(3),date:s(4),refs:s(5)});}}let mut staged=Vec::new();let mut unstaged=Vec::new();let status_bytes=git(&p,&["status","--porcelain=v1","-z","-uall"])?;let mut records=status_bytes.split(|b|*b==0);while let Some(row)=records.next(){if row.len()<4{continue}let(x,y)=(row[0],row[1]);let path=String::from_utf8(row[3..].to_vec()).map_err(|_|String::from("Non UTF-8 path"))?;if matches!(x,b'R'|b'C')||matches!(y,b'R'|b'C'){let _=records.next();}if !matches!(x,b' '|b'?'|b'!'){staged.push(path.clone());}if !matches!(y,b' '|b'!'){unstaged.push(path);}}staged.sort();staged.dedup();unstaged.sort();unstaged.dedup();Ok(Snapshot{branches,log,staged,unstaged})}).await.map_err(|e|e.to_string())?}
fn blob(p:&Path,spec:&str)->Result<String,String>{let out=Command::new("git").arg("-C").arg(p).args(["show",spec]).output().map_err(|e|e.to_string())?;if !out.status.success(){return Ok(String::new())}if out.stdout.len()>5_000_000||out.stdout.contains(&0){return Err("Binary or oversized Diff is not supported".into())}String::from_utf8(out.stdout).map_err(|_|"Diff requires UTF-8".into())}
#[tauri::command]pub async fn git_diff(root:String,path:String,kind:String,commit:String)->Result<Diff,String>{tauri::async_runtime::spawn_blocking(move||{relative(&path)?;let p=root_path(&root)?;match kind.as_str(){"staged"=>Ok(Diff{before:blob(&p,&format!("HEAD:{}",path))?,after:blob(&p,&format!(":{}",path))?}),"commit"=>{if commit.len()!=40||!commit.bytes().all(|b|b.is_ascii_hexdigit()){return Err("Invalid commit".into())}Ok(Diff{before:blob(&p,&format!("{}^:{}",commit,path))?,after:blob(&p,&format!("{}:{}",commit,path))?})},"unstaged"=>{let after=if p.join(&path).exists(){read_document_sync(root,path.clone())?.content}else{String::new()};Ok(Diff{before:blob(&p,&format!(":{}",path))?,after})},_=>Err("Unknown comparison".into())}}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn commit_files(root:String,commit:String)->Result<Vec<String>,String>{tauri::async_runtime::spawn_blocking(move||{if commit.len()!=40||!commit.bytes().all(|b|b.is_ascii_hexdigit()){return Err("Invalid commit".into())}let p=root_path(&root)?;Ok(git(&p,&["show","--first-parent","--format=","--name-only","-z",&commit])?.split(|b|*b==0).filter(|b|!b.is_empty()).map(|b|String::from_utf8_lossy(b).into()).collect())}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn git_write(root:String,action:String,value:String)->Result<String,String>{tauri::async_runtime::spawn_blocking(move||{let _lock=WRITE.lock().map_err(|_|"Git operation lock failed")?;let p=root_path(&root)?;match action.as_str(){"stage"|"unstage"=>{relative(&value)?;if action=="stage"{if p.join(&value).exists(){checked_in(&p,&value)?;}git(&p,&["--literal-pathspecs","add","--",&value])?;}else if git(&p,&["rev-parse","--verify","HEAD"]).is_ok(){git(&p,&["--literal-pathspecs","restore","--staged","--",&value])?;}else{git(&p,&["--literal-pathspecs","rm","--cached","--",&value])?;}},"stage_all"=>{git(&p,&["add","-A"])?;},"unstage_all"=>{if git(&p,&["rev-parse","--verify","HEAD"]).is_ok(){git(&p,&["restore","--staged","."])?;}else{git(&p,&["rm","-r","--cached","--ignore-unmatch","."])?;}},"discard"=>{relative(&value)?;let has_head=git(&p,&["rev-parse","--verify","HEAD"]).is_ok();if has_head&&git(&p,&["cat-file","-e",&format!("HEAD:{}",value)]).is_ok(){git(&p,&["--literal-pathspecs","restore","--source=HEAD","--staged","--worktree","--",&value])?;}else if git(&p,&["ls-files","--error-unmatch","--",&value]).is_ok(){git(&p,&["--literal-pathspecs","rm","-f","--",&value])?;}else if p.join(&value).exists(){let target=checked_in(&p,&value)?;fs::remove_file(target).map_err(|e|e.to_string())?;}},"commit"=>{if value.trim().is_empty(){return Err("Commit message is required".into())}git(&p,&["commit","-m",&value])?;},"checkout"|"merge"|"create"|"delete"=>{git(&p,&["check-ref-format","--branch",&value])?;if action=="checkout"||action=="merge"{if !git(&p,&["status","--porcelain"])?.is_empty(){return Err("Commit or otherwise handle local changes before checkout/merge".into())}}match action.as_str(){"checkout"=>{git(&p,&["switch","--",&value])?;},"merge"=>{git(&p,&["merge","--",&value])?;},"create"=>{git(&p,&["branch","--",&value])?;},_=>{git(&p,&["branch","-d","--",&value])?;}}},_=>return Err("Unsupported Git operation".into())}Ok("Git operation completed".into())}).await.map_err(|e|e.to_string())?}
#[cfg(test)]mod tests{use super::*;#[test]fn reject_paths(){for s in ["../secret","/tmp/file","a/../b",".git/config",""]{assert!(relative(s).is_err())}assert!(relative("src/a file.ts").is_ok());}#[test]fn staging_and_diff(){let p=std::env::temp_dir().join(format!("branchdesk-test-{}",std::process::id()));fs::create_dir_all(&p).unwrap();git(&p,&["init"]).unwrap();fs::write(p.join("a file.txt"),"hello\n").unwrap();git(&p,&["add","--","a file.txt"]).unwrap();assert_eq!(blob(&p,":a file.txt").unwrap(),"hello\n");fs::remove_dir_all(p).unwrap();}#[test]fn merge_commit_files_listed(){let p=std::env::temp_dir().join(format!("branchdesk-merge-{}",std::process::id()));fs::create_dir_all(&p).unwrap();git(&p,&["init","-b","main"]).unwrap();git(&p,&["config","user.name","Test"]).unwrap();git(&p,&["config","user.email","test@example.test"]).unwrap();fs::write(p.join("base.txt"),"base\n").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","base"]).unwrap();let root_commit=text(git(&p,&["rev-parse","HEAD"]).unwrap());let root_files:Vec<String>=git(&p,&["show","--first-parent","--format=","--name-only","-z",&root_commit]).unwrap().split(|b|*b==0).filter(|b|!b.is_empty()).map(|b|String::from_utf8_lossy(b).into()).collect();assert_eq!(root_files,vec!["base.txt"]);git(&p,&["switch","-c","feat"]).unwrap();fs::write(p.join("feat.txt"),"feat\n").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","feat"]).unwrap();git(&p,&["switch","main"]).unwrap();fs::write(p.join("main.txt"),"main\n").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","main"]).unwrap();git(&p,&["merge","--no-ff","feat","-m","merge feat"]).unwrap();let head=text(git(&p,&["rev-parse","HEAD"]).unwrap());let files:Vec<String>=git(&p,&["show","--first-parent","--format=","--name-only","-z",&head]).unwrap().split(|b|*b==0).filter(|b|!b.is_empty()).map(|b|String::from_utf8_lossy(b).into()).collect();assert_eq!(files,vec!["feat.txt"]);fs::remove_dir_all(p).unwrap();}}
#[tauri::command]pub async fn file_history(root:String,path:String)->Result<Vec<Commit>,String>{tauri::async_runtime::spawn_blocking(move||{relative(&path)?;let p=root_path(&root)?;if git(&p,&["rev-parse","--verify","HEAD"]).is_err(){return Ok(vec![])}let bytes=git(&p,&["--literal-pathspecs","log","-100","--format=%H%x00%P%x00%s%x00%an%x00%ai%x00%D%x00","--",&path])?;let fields:Vec<_>=bytes.split(|b|*b==0).collect();let mut log=vec![];for f in fields.chunks(6){if f.len()<6{break}let s=|i:usize|String::from_utf8_lossy(f[i]).trim().to_string();log.push(Commit{hash:s(0),parents:s(1).split_whitespace().map(str::to_string).collect(),subject:s(2),author:s(3),date:s(4),refs:s(5)});}Ok(log)}).await.map_err(|e|e.to_string())?}
#[cfg(test)]mod history_tests{use super::*;#[test]fn history_filters_exact_path(){let p=std::env::temp_dir().join(format!("branchdesk-history-{}",std::process::id()));fs::create_dir_all(&p).unwrap();git(&p,&["init"]).unwrap();git(&p,&["config","user.name","Test"]).unwrap();git(&p,&["config","user.email","test@example.test"]).unwrap();fs::write(p.join("a [1].txt"),"a").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","first"]).unwrap();fs::write(p.join("other.txt"),"b").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","unrelated"]).unwrap();let log=text(git(&p,&["--literal-pathspecs","log","--format=%s","--","a [1].txt"]).unwrap());assert_eq!(log,"first");fs::remove_dir_all(p).unwrap();}}
#[derive(Serialize)]pub struct Workflow{pub merging:bool,pub conflicts:Vec<String>,pub remotes:Vec<String>,pub upstream:String,pub branch:String}
fn workflow(p:&Path)->Result<Workflow,String>{let merge_path=text(git(p,&["rev-parse","--git-path","MERGE_HEAD"])?);let merging=p.join(merge_path).exists();let conflicts=git(p,&["diff","--name-only","--diff-filter=U","-z"])?.split(|b|*b==0).filter(|b|!b.is_empty()).map(|b|String::from_utf8_lossy(b).into()).collect();Ok(Workflow{merging,conflicts,remotes:text(git(p,&["remote"])?).lines().map(str::to_string).collect(),upstream:git(p,&["rev-parse","--abbrev-ref","@{upstream}"]).map(text).unwrap_or_default(),branch:text(git(p,&["branch","--show-current"])?)})}
#[tauri::command]pub async fn git_workflow(root:String)->Result<Workflow,String>{tauri::async_runtime::spawn_blocking(move||workflow(&root_path(&root)?)).await.map_err(|e|e.to_string())?}
fn remote_name(state:&Workflow,action:&str,value:&str)->Result<String,String>{match action{"fetch"|"push"=>state.remotes.iter().find(|r|r.as_str()==value).cloned().ok_or_else(||"Select a valid remote".into()),"pull"=>state.upstream.split_once('/').map(|(remote,_)|remote.to_string()).ok_or_else(||"Current branch has no upstream; push it first".into()),_=>Err("Authentication is only available for Fetch, Pull and Push".into())}}
fn remote_url(p:&Path,state:&Workflow,action:&str,value:&str)->Result<String,String>{let remote=remote_name(state,action,value)?;Ok(text(git(p,&["remote","get-url",&remote])?))}
fn auth_failure(message:&str)->bool{["could not read Username","could not read Password","Authentication failed","authentication required","terminal prompts disabled"].iter().any(|needle|message.contains(needle))}
fn network_git(p:&Path,args:&[&str],url:&str)->Result<Vec<u8>,String>{let out=Command::new("git").arg("-C").arg(p).args(args).env("GIT_TERMINAL_PROMPT","0").output().map_err(|e|e.to_string())?;if out.status.success(){return Ok(out.stdout)}let error=String::from_utf8_lossy(&out.stderr).trim().to_string();if (url.starts_with("http://")||url.starts_with("https://"))&&auth_failure(&error){Err(format!("AUTH_REQUIRED\n{}\n{}",url,error))}else{Err(error)}}
fn credential(p:&Path,operation:&str,url:&str,username:&str,password:&str)->Result<(),String>{let mut child=Command::new("git").arg("-C").arg(p).args(["credential",operation]).stdin(Stdio::piped()).stdout(Stdio::null()).stderr(Stdio::piped()).spawn().map_err(|e|e.to_string())?;let input=if operation=="approve"{format!("url={}\nusername={}\npassword={}\n\n",url,username,password)}else{format!("url={}\nusername={}\n\n",url,username)};child.stdin.take().ok_or("Unable to open Git credential input")?.write_all(input.as_bytes()).map_err(|e|e.to_string())?;let output=child.wait_with_output().map_err(|e|e.to_string())?;if output.status.success(){Ok(())}else{Err(String::from_utf8_lossy(&output.stderr).trim().to_string())}}
fn workflow_action(p:&Path,action:&str,value:&str)->Result<String,String>{let state=workflow(p)?;match action{
"resolve"=>{relative(value)?;git(p,&["--literal-pathspecs","add","-A","--",value])?;},
"continue"=>{if !state.merging||!state.conflicts.is_empty(){return Err("Resolve all conflicts before continuing the merge".into())}git(p,&["-c","core.editor=true","commit","--no-edit"])?;},
"abort"=>{if !state.merging{return Err("No merge is in progress".into())}git(p,&["merge","--abort"])?;},
"fetch"=>{let url=remote_url(p,&state,action,value)?;network_git(p,&["fetch","--",value],&url)?;},
"pull"=>{if state.merging||!git(p,&["status","--porcelain"])?.is_empty(){return Err("Commit or handle local changes before updating".into())}let url=remote_url(p,&state,action,value)?;network_git(p,&["pull","--ff-only"],&url)?;},
"push"=>{if state.merging||!state.conflicts.is_empty(){return Err("Finish the merge before pushing".into())}if state.branch.is_empty(){return Err("Cannot push detached HEAD".into())}let url=remote_url(p,&state,action,value)?;network_git(p,&["push","--set-upstream","--",value,&format!("HEAD:refs/heads/{}",state.branch)],&url)?;},
"checkout_remote"=>{if state.merging||!git(p,&["status","--porcelain"])?.is_empty(){return Err("Commit or handle local changes before checkout".into())}let full=format!("refs/remotes/{}",value);git(p,&["show-ref","--verify",&full])?;let remote=state.remotes.iter().filter(|r|value.starts_with(&format!("{}/",r))).max_by_key(|r|r.len()).ok_or("Unknown remote")?;let local=&value[remote.len()+1..];git(p,&["check-ref-format","--branch",local])?;if git(p,&["show-ref","--verify",&format!("refs/heads/{}",local)]).is_ok(){return Err(format!("Local branch {} already exists. Select it under Local instead.",local))}git(p,&["switch","--track","-c",local,&full])?;},_=>return Err("Unsupported workflow action".into())}Ok(format!("{} completed",action))}
#[tauri::command]pub async fn git_workflow_action(root:String,action:String,value:String)->Result<String,String>{tauri::async_runtime::spawn_blocking(move||{let _lock=WRITE.lock().map_err(|_|"Git lock failed")?;workflow_action(&root_path(&root)?,&action,&value)}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn git_workflow_auth(root:String,action:String,value:String,username:String,password:String)->Result<String,String>{tauri::async_runtime::spawn_blocking(move||{if username.trim().is_empty()||password.is_empty(){return Err("Username and password or token are required".into())}let _lock=WRITE.lock().map_err(|_|"Git lock failed")?;let p=root_path(&root)?;let state=workflow(&p)?;let url=remote_url(&p,&state,&action,&value)?;if !(url.starts_with("http://")||url.starts_with("https://")){return Err("Interactive credentials are only supported for HTTP and HTTPS remotes".into())}credential(&p,"approve",&url,username.trim(),&password)?;match workflow_action(&p,&action,&value){Ok(message)=>Ok(message),Err(error)=>{let _=credential(&p,"reject",&url,username.trim(),"");Err(error.strip_prefix("AUTH_REQUIRED\n").and_then(|rest|rest.split_once('\n').map(|(_,message)|message.to_string())).unwrap_or(error))}}}).await.map_err(|e|e.to_string())?}
#[cfg(test)]mod workflow_tests{use super::*;#[test]fn remote_and_conflict_lifecycle(){let dir=std::env::temp_dir().join(format!("branchdesk-flow-{}",std::process::id()));let p=dir.join("work");let bare=dir.join("remote.git");fs::create_dir_all(&p).unwrap();fs::create_dir_all(&bare).unwrap();git(&bare,&["init","--bare"]).unwrap();git(&p,&["init","-b","main"]).unwrap();git(&p,&["config","user.name","Test"]).unwrap();git(&p,&["config","user.email","test@example.test"]).unwrap();fs::write(p.join("a"),"base\n").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","base"]).unwrap();git(&p,&["remote","add","origin",bare.to_str().unwrap()]).unwrap();workflow_action(&p,"push","origin").unwrap();workflow_action(&p,"fetch","origin").unwrap();workflow_action(&p,"pull","").unwrap();git(&p,&["branch","topic"]).unwrap();git(&p,&["push","origin","topic"]).unwrap();git(&p,&["branch","-d","topic"]).unwrap();workflow_action(&p,"checkout_remote","origin/topic").unwrap();assert_eq!(workflow(&p).unwrap().upstream,"origin/topic");fs::write(p.join("a"),"topic\n").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","topic"]).unwrap();git(&p,&["switch","main"]).unwrap();fs::write(p.join("a"),"main\n").unwrap();git(&p,&["add","."]).unwrap();git(&p,&["commit","-m","main"]).unwrap();assert!(git(&p,&["merge","topic"]).is_err());assert_eq!(workflow(&p).unwrap().conflicts,vec!["a"]);assert!(workflow_action(&p,"continue","").is_err());workflow_action(&p,"abort","").unwrap();assert!(!workflow(&p).unwrap().merging);assert!(git(&p,&["merge","topic"]).is_err());fs::write(p.join("a"),"resolved\n").unwrap();workflow_action(&p,"resolve","a").unwrap();workflow_action(&p,"continue","").unwrap();assert!(!workflow(&p).unwrap().merging);fs::remove_dir_all(dir).unwrap();}}

#[cfg(test)]
mod credential_tests{
    use super::*;

    #[test]
    fn recognizes_interactive_auth_failures(){
        assert!(auth_failure("fatal: could not read Username for 'https://example.test'"));
        assert!(auth_failure("fatal: Authentication failed"));
        assert!(!auth_failure("fatal: unable to access: connection refused"));
    }
}
